def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strong_opp = 0
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 85:
                    strong_opp += 1

    if not alive:
        return float(min(budget, 18.0))

    low_supply = supply <= 17
    high_supply = supply >= 22
    urgent = hp <= 3 or no_water_days >= 2
    semi_urgent = hp <= 5 or no_water_days >= 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if urgent:
        if low_supply:
            bid = max(110.0, highest_prev + 3.0)
        else:
            bid = max(88.0, avg_prev + 2.0)
        return float(min(budget, bid))

    if low_supply:
        if highest_prev >= 120:
            bid = 72.0
        elif highest_prev >= 95:
            bid = 84.0
        else:
            bid = max(76.0, highest_prev + 1.5)
    elif high_supply:
        if strong_opp >= 2:
            bid = 24.0
        else:
            bid = 34.0
    else:
        if highest_prev >= 120:
            bid = 42.0
        elif highest_prev >= 95:
            bid = 52.0
        else:
            bid = 58.0

    if semi_urgent:
        bid += 18.0
    if day >= 8 and hp <= 6:
        bid += 12.0

    reserve_floor = 10.0 if hp > 5 else 0.0
    bid = min(bid, max(0.0, budget - reserve_floor))
    bid = max(0.0, bid)
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    if day_context['supply'] < 18:
        return min(my_status['budget'], max(avg_opp_bid + 5.0, 80.0))

    return min(my_status['budget'], max(avg_opp_bid * 0.8, 40.0))
